analyze.mjs.text:
// Classifies one HTTP response's security headers (a real response
// collected by probe.mjs's live network request, or pasted in by hand) into
// named clickjacking and Content-Security-Policy misconfiguration patterns.
//
// Pure function, no I/O, no network -- this is the module both the CLI
// (check.mjs, which fetches for real) and the browser page (index.html,
// which can only ever analyse a payload someone already fetched) import, so
// the classification logic exists exactly once.
//
// The value here isn't reading four header names -- curl -I does that. It's
// getting the CSP fallback rules right, the way a developer who has to know
// them by heart already does and a naive grep does not:
//
//   * `frame-ancestors` does NOT fall back to `default-src`. It is a
//     navigation directive, not a fetch directive, so a policy with
//     `default-src 'self'` and no explicit `frame-ancestors` gives the page
//     *no* frame protection from CSP at all -- only X-Frame-Options can
//     cover that gap.
//   * `script-src` DOES fall back to `default-src` when script-src is
//     absent from the policy entirely.
//   * `X-Frame-Options: ALLOW-FROM ...` is silently ignored by every
//     current major browser engine (it was dropped after CSP2 shipped
//     frame-ancestors) -- a site relying on it looks protected in a header
//     dump and is not actually protected in a real browser today.
//   * A nonce- or hash-source alongside `'unsafe-inline'` in a fetch
//     directive makes CSP2+ browsers ignore `'unsafe-inline'` entirely
//     (kept only for CSP1 backwards compatibility) -- so `'unsafe-inline'`
//     is only a live finding when no nonce/hash is also present.

const FRAME_TOKEN_RE = /^-?[A-Za-z0-9]/;

/** Parses a Content-Security-Policy (or -Report-Only) header value into a
 * Map of directive name -> array of lowercased source-list tokens. Multiple
 * directives of the same name in one header keep only the first, per spec
 * (later duplicates are ignored by browsers). */
export function parseCsp(headerValue) {
  const map = new Map();
  if (typeof headerValue !== 'string' || headerValue.trim() === '') return map;
  for (const rawDirective of headerValue.split(';')) {
    const trimmed = rawDirective.trim();
    if (!trimmed) continue;
    const parts = trimmed.split(/\s+/);
    const name = parts[0].toLowerCase();
    if (!FRAME_TOKEN_RE.test(name) || map.has(name)) continue;
    map.set(name, parts.slice(1).map((t) => t.toLowerCase()));
  }
  return map;
}

function effectiveScriptSrc(csp) {
  if (csp.has('script-src')) return csp.get('script-src');
  if (csp.has('default-src')) return csp.get('default-src');
  return null;
}

function hasNonceOrHash(tokens) {
  return tokens.some((t) => t.startsWith("'nonce-") || /^'sha(256|384|512)-/.test(t));
}

function norm(value) {
  return typeof value === 'string' ? value.trim() : null;
}

/**
 * @param {string} target - the URL that was probed (for display only)
 * @param {{ok: boolean, status: number|null, protocol: string|null,
 *   headers: Record<string,string|null>, error: string|null}} probe
 * @returns {{target: string, probe: object, findings: object[],
 *   dangerCount: number, noticeCount: number, ok: boolean, incomplete: boolean}}
 */
export function buildReport(target, probe) {
  const p = probe && typeof probe === 'object' ? probe : { ok: false };
  const incomplete = p.ok === false;
  const findings = [];
  const headers = p.headers ?? {};

  const cspHeader = norm(headers['content-security-policy']);
  const cspReportOnly = norm(headers['content-security-policy-report-only']);
  const xfo = norm(headers['x-frame-options']);
  const hsts = norm(headers['strict-transport-security']);

  if (!incomplete) {
    const csp = cspHeader ? parseCsp(cspHeader) : new Map();

    // --- Clickjacking / frame protection -----------------------------
    if (csp.has('frame-ancestors')) {
      // Protected: CSP frame-ancestors is present and takes precedence over
      // X-Frame-Options in every current browser. No finding either way.
    } else if (xfo && /^allow-from\b/i.test(xfo)) {
      findings.push({
        id: 'frame-options-allow-from-ignored',
        severity: 'danger',
        title: 'X-Frame-Options: ALLOW-FROM is ignored by current browsers',
        detail:
          `The response sent X-Frame-Options: ${xfo}, but every current major browser engine ` +
          "dropped support for the ALLOW-FROM directive value once CSP2's frame-ancestors " +
          'shipped. The header looks like frame protection in a raw dump and provides none in a ' +
          "real browser today -- add a CSP frame-ancestors directive (it isn't a fallback for " +
          'this header, it replaces it).',
        evidenceHeader: `x-frame-options: ${xfo}`,
      });
    } else if (!xfo) {
      findings.push({
        id: 'missing-frame-protection',
        severity: 'danger',
        title: 'No clickjacking protection (frame-ancestors or X-Frame-Options)',
        detail:
          'Neither a Content-Security-Policy frame-ancestors directive nor an X-Frame-Options ' +
          'header is present, so any site on the web can load this page in an iframe and overlay ' +
          "it to trick a visitor into clicking something they didn't mean to -- the classic " +
          'clickjacking attack.',
        evidenceHeader: 'x-frame-options: (not set); content-security-policy frame-ancestors: (not set)',
      });
    }
    // else: X-Frame-Options is present with a value other than ALLOW-FROM
    // (DENY, SAMEORIGIN, or anything else current browsers still honour
    // enough to constrain framing) -- protected, no finding.

    // --- Content-Security-Policy strength -----------------------------
    if (!cspHeader && !cspReportOnly) {
      findings.push({
        id: 'missing-csp',
        severity: 'notice',
        title: 'No Content-Security-Policy header at all',
        detail:
          'Neither Content-Security-Policy nor Content-Security-Policy-Report-Only is present. ' +
          'CSP is the strongest browser-side mitigation against script injection (XSS) and, via ' +
          'frame-ancestors, clickjacking -- this response has none of that defence-in-depth.',
        evidenceHeader: 'content-security-policy: (not set)',
      });
    } else if (!cspHeader && cspReportOnly) {
      findings.push({
        id: 'csp-report-only-not-enforced',
        severity: 'notice',
        title: 'CSP is report-only, not enforced',
        detail:
          'Only Content-Security-Policy-Report-Only is set. The browser will report violations ' +
          'to the configured endpoint but will not block anything -- an attacker-injected script ' +
          'still runs. This is a normal rollout stage, not a finished deployment.',
        evidenceHeader: `content-security-policy-report-only: ${cspReportOnly}`,
      });
    }

    if (cspHeader) {
      const scriptSrc = effectiveScriptSrc(csp);
      if (scriptSrc) {
        const usedDirective = csp.has('script-src') ? 'script-src' : 'default-src';
        if (scriptSrc.includes("'unsafe-inline'") && !hasNonceOrHash(scriptSrc)) {
          findings.push({
            id: 'csp-unsafe-inline-script',
            severity: 'danger',
            title: `CSP ${usedDirective} allows 'unsafe-inline' with no nonce or hash`,
            detail:
              `The effective script-src (from ${usedDirective}) includes 'unsafe-inline' and no ` +
              "nonce-/hash-source to override it. In every CSP2+ browser a nonce or hash source " +
              "makes 'unsafe-inline' ignored (kept only for CSP1 fallback) -- without one, this " +
              'policy does not block inline script injection at all, which is the exact attack ' +
              'class CSP exists to stop.',
            evidenceHeader: `content-security-policy: ${cspHeader}`,
          });
        }
        const wildcardToken = scriptSrc.find((t) => t === '*' || t === 'http:' || t === 'https:' || t === 'data:');
        if (wildcardToken) {
          findings.push({
            id: 'csp-wildcard-script-src',
            severity: 'danger',
            title: `CSP ${usedDirective} allows scripts from ${wildcardToken === '*' ? 'any host' : `any ${wildcardToken} URL`}`,
            detail:
              `The effective script-src (from ${usedDirective}) includes the token "${wildcardToken}", ` +
              'which permits loading script from any host on that scheme (or any host at all, for ' +
              "\"*\"). A policy this broad does not meaningfully restrict where script can be " +
              'loaded from, regardless of nonces or hashes elsewhere in the directive.',
            evidenceHeader: `content-security-policy: ${cspHeader}`,
          });
        }
      }
    }

    // --- HSTS -----------------------------------------------------------
    if (p.protocol === 'https:' && !hsts) {
      findings.push({
        id: 'missing-hsts',
        severity: 'notice',
        title: 'No Strict-Transport-Security header on an HTTPS response',
        detail:
          "This response was served over HTTPS but sent no Strict-Transport-Security header, so " +
          "a browser has no instruction to refuse a later plain-HTTP connection to this host -- " +
          "leaving a window for a downgrade / SSL-stripping attack on a visitor's next visit.",
        evidenceHeader: 'strict-transport-security: (not set)',
      });
    }
  }

  const dangerCount = findings.filter((f) => f.severity === 'danger').length;
  const noticeCount = findings.filter((f) => f.severity === 'notice').length;

  return {
    target,
    probe: {
      ok: p.ok !== false,
      status: p.status ?? null,
      protocol: p.protocol ?? null,
      headers: {
        'content-security-policy': cspHeader,
        'content-security-policy-report-only': cspReportOnly,
        'x-frame-options': xfo,
        'strict-transport-security': hsts,
      },
      error: p.error ?? null,
    },
    findings,
    dangerCount,
    noticeCount,
    ok: !incomplete && dangerCount === 0,
    incomplete,
  };
}

check.mjs.text:
#!/usr/bin/env node
// CLI: sends one real GET request to a URL you name and reports which
// clickjacking and Content-Security-Policy misconfiguration patterns the
// response headers show. Your machine, your network -- no request goes
// through this portfolio or anywhere but the URL you pass.
//
//   node check.mjs <url> [--json] [--timeout <ms>]
//
// Only point this at a system you own or are authorised to test. This
// sends one ordinary, unauthenticated GET request -- nothing here bypasses
// authentication, reads protected data, or does anything a browser
// wouldn't also do by visiting the URL -- but treat it the same as you
// would curl or any other request tool aimed at someone else's server.
//
// Exit code 0 when the probe completed and no "danger"-severity finding is
// present; 1 when a danger finding is present or the probe failed to
// complete (network error, timeout, bad URL).

import { runProbe } from './probe.mjs';
import { buildReport } from './analyze.mjs';

function formatText(report) {
  const lines = [];
  lines.push(`Target: ${report.target}`);
  if (!report.probe.ok) {
    lines.push(`Request failed: ${report.probe.error}`);
    lines.push('');
    lines.push('The probe did not complete -- re-run once the target is reachable.');
    return lines.join('\n');
  }
  lines.push(`Status: ${report.probe.status}  (${report.probe.protocol ?? 'unknown scheme'})`);
  lines.push('');
  lines.push(`  content-security-policy: ${report.probe.headers['content-security-policy'] ?? '(not set)'}`);
  lines.push(`  content-security-policy-report-only: ${report.probe.headers['content-security-policy-report-only'] ?? '(not set)'}`);
  lines.push(`  x-frame-options: ${report.probe.headers['x-frame-options'] ?? '(not set)'}`);
  lines.push(`  strict-transport-security: ${report.probe.headers['strict-transport-security'] ?? '(not set)'}`);
  lines.push('');

  if (report.findings.length === 0) {
    lines.push('None of the patterns this tool checks for were found.');
  } else {
    for (const f of report.findings) {
      const mark = f.severity === 'danger' ? '!!' : '--';
      lines.push(`${mark} [${f.severity.toUpperCase()}] ${f.title}`);
      lines.push(`     ${f.detail}`);
      lines.push(`     evidence: ${f.evidenceHeader}`);
      lines.push('');
    }
  }

  lines.push(
    'This is evidence from this one response, not a full security assessment -- ' +
      'see README.md for what this tool does and does not check.',
  );
  return lines.join('\n');
}

function parseArgs(argv) {
  const args = { target: null, json: false, timeoutMs: undefined };
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--json') args.json = true;
    else if (argv[i] === '--timeout') args.timeoutMs = Number(argv[++i]);
    else if (!args.target && !argv[i].startsWith('--')) args.target = argv[i];
  }
  return args;
}

/** Pure orchestration: given a probe function (real network, or a stub in
 * tests), fetch and classify. Kept separate from main() so tests can inject
 * a fake `probeFn` instead of hitting the network. */
export async function runCheck(target, { probeFn = runProbe, timeoutMs } = {}) {
  const probe = await probeFn(target, timeoutMs ? { timeoutMs } : {});
  return buildReport(target, probe);
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.target) {
    console.error('Usage: node check.mjs <url> [--json] [--timeout <ms>]');
    process.exit(2);
  }
  try {
    // eslint-disable-next-line no-new
    new URL(args.target);
  } catch {
    console.error(`Not a valid URL: ${args.target}`);
    process.exit(2);
  }

  const report = await runCheck(args.target, { timeoutMs: args.timeoutMs });

  if (args.json) {
    console.log(JSON.stringify({ target: report.target, probe: report.probe }, null, 2));
  } else {
    console.log(formatText(report));
  }
  process.exit(report.ok ? 0 : 1);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

probe.mjs.text:
// Sends the one real HTTP request this check depends on: a GET to the
// target URL, reading back the response security headers that matter for
// clickjacking (frame-ancestors / X-Frame-Options) and Content-Security-
// Policy strength. Node's built-in http/https clients are used, and no
// redirect is followed automatically -- a 3xx response is reported as-is,
// with its own headers, rather than silently chasing the Location so a
// caller always knows exactly which response the report describes.
//
// This module only ever talks to the one target URL a caller names. It
// makes no other network call, reads no local files, and sends nothing
// anywhere else.

import { request as httpRequest } from 'node:http';
import { request as httpsRequest } from 'node:https';

const DEFAULT_TIMEOUT_MS = 10_000;
const USER_AGENT =
  'security-headers-check/1 (+https://duncan-haywood.github.io/monorepo-projects/security-headers-check/)';

const HEADER_NAMES = [
  'content-security-policy',
  'content-security-policy-report-only',
  'x-frame-options',
  'strict-transport-security',
];

function headerValue(headers, name) {
  const value = headers[name.toLowerCase()];
  if (value == null) return null;
  return Array.isArray(value) ? value.join(', ') : String(value);
}

/**
 * One GET request to `targetUrl`. Resolves rather than rejects on any
 * failure so a caller never needs a try/catch around it.
 */
export function sendProbe(targetUrl, { timeoutMs = DEFAULT_TIMEOUT_MS } = {}) {
  return new Promise((resolve) => {
    let parsed;
    try {
      parsed = new URL(targetUrl);
    } catch (err) {
      resolve({ ok: false, status: null, protocol: null, headers: {}, error: `invalid URL: ${err.message}` });
      return;
    }
    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
      resolve({ ok: false, status: null, protocol: null, headers: {}, error: `unsupported scheme: ${parsed.protocol}` });
      return;
    }

    const requester = parsed.protocol === 'https:' ? httpsRequest : httpRequest;
    const headers = { 'user-agent': USER_AGENT, accept: 'text/html,*/*' };

    let settled = false;
    const finish = (result) => {
      if (settled) return;
      settled = true;
      resolve(result);
    };

    const req = requester(
      parsed,
      { method: 'GET', headers, timeout: timeoutMs },
      (res) => {
        res.on('data', () => {}); // headers are all this check needs; drain and discard the body
        res.on('end', () => {
          const out = {};
          for (const name of HEADER_NAMES) out[name] = headerValue(res.headers, name);
          finish({
            ok: true,
            status: res.statusCode ?? null,
            protocol: parsed.protocol,
            headers: out,
            error: null,
          });
        });
        res.on('error', (err) => finish({ ok: false, status: res.statusCode ?? null, protocol: parsed.protocol, headers: {}, error: err.message }));
      },
    );
    req.on('timeout', () => req.destroy(new Error('timed out')));
    req.on('error', (err) => finish({ ok: false, status: null, protocol: parsed.protocol, headers: {}, error: err.message }));
    req.end();
  });
}

/** Runs the single probe against `targetUrl` and returns the raw result
 * (same shape `analyze.mjs`'s `buildReport` expects). */
export async function runProbe(targetUrl, opts = {}) {
  return { target: targetUrl, ...(await sendProbe(targetUrl, opts)) };
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores the
// target URL, the pasted probe JSON, or anything about what was checked --
// that is exactly the kind of thing that must not be transmitted anywhere,
// and this tool never reads it off the visitor's machine either.

const STORAGE_KEY = 'security-headers-check-usage';

function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'check_run') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const current = JSON.parse(storage.getItem(STORAGE_KEY) || '{}');
    current[event] = (current[event] || 0) + 1;
    current.last_day = today;
    storage.setItem(STORAGE_KEY, JSON.stringify(current));
  } catch {
    // A browser refusing site data must not stop the page computing a result.
  }
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. `recordUsage` above consults it
// directly as well as taking the caller's argument -- a stored preference
// that only one line of page wiring reads is one line away from being
// forgotten, which is the defect this change exists to fix.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${STORAGE_KEY}-opt-out`) === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem(STORAGE_KEY); } catch { /* storage is optional */ }
    try { storage.setItem(`${STORAGE_KEY}-opt-out`, '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem(`${STORAGE_KEY}-opt-out`); } catch { /* storage is optional */ }
  }
}
